    parameter [BAND*COEFF_W-1:0] GAIN = {32'd2, 32'd0, 32'd1}
)(
    input logic clk,
    input logic reset_n,
    input logic [DATA_W-1:0] data_in,
    output logic [DATA_W-1:0] data_out
);

    logic signed [DATA_W-1:0] data_band [0:BAND-1];
    logic signed [COEFF_W-1:0] gain [0:BAND-1];
    logic signed [63:0] reg_out;

    generate
        genvar i;
        for (i = 0; i < BAND; i++) begin : create_fir_filter
            FIR #(.N_TAPS(N_TAPS), .COEFF_W(COEFF_W), .DATA_W(DATA_W), .COEFFS(COEFFS[N_TAPS*COEFF_W*i +: N_TAPS*COEFF_W])) fir (
                .clk(clk),
                .reset_n(reset_n),
                .data_in(data_in),
                .data_out(data_band[i])
            );
        end
    endgenerate

    generate 
        genvar j;
        for (j = 0; j < BAND; j++) begin : initial_gain
            assign gain[j] = GAIN[COEFF_W*j +: COEFF_W];
        end
    endgenerate

    always_comb begin
        reg_out = 0;
        for (int i = 0; i < BAND; i++) begin
            reg_out += data_band[i] * gain[i];
        end
    end

    assign data_out = reg_out;


endmodule